import {
    useCallback, useEffect, useId, useRef, useState,
    type ComponentProps, type ReactNode,
} from "react";
import * as PortalPrimitive from "@radix-ui/react-portal";
import { cn } from "./utils";
import { usePortalContainer } from "./foundation/portal-scope";

type ToastRegionProps = ComponentProps<"div"> & {
    placement?: "top-right" | "bottom-right" | "bottom-left";
    portal?: boolean;
} & Pick<ComponentProps<typeof PortalPrimitive.Root>, "container">;

function ToastRegion({
    placement = "bottom-right",
    portal = true,
    container,
    className,
    ...props
}: ToastRegionProps) {
    const portalContainer = usePortalContainer(container);
    const content = (
        <div
            className={cn(
                "pointer-events-none fixed z-50 grid w-[min(24rem,calc(100vw-2rem))] " +
                "gap-[var(--space-2)]",
                placement === "top-right" && "right-4 top-4",
                placement === "bottom-right" && "bottom-4 right-4",
                placement === "bottom-left" && "bottom-4 left-4",
                className,
            )}
            {...props}
        />
    );
    return portal ? <PortalPrimitive.Root asChild container={portalContainer}>
        {content}
    </PortalPrimitive.Root> : content;
}

type ToastProps = Omit<ComponentProps<"div">, "title"> & {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    title: string;
    description?: ReactNode;
    action?: ReactNode;
    variant?: "info" | "success" | "warning" | "error";
    statusLabel?: string;
    closeLabel?: string;
    /** Milliseconds before dismissal. Zero keeps the notification open. */
    duration?: number;
    paused?: boolean;
};

const variantLabel = {
    info: "Info",
    success: "Success",
    warning: "Warning",
    error: "Error",
} as const;

function useToastElementRef(forwardedRef: ComponentProps<"div">["ref"]) {
    const localRef = useRef<HTMLDivElement>(null);
    const setRef = useCallback((node: HTMLDivElement | null) => {
        localRef.current = node;
        if (typeof forwardedRef === "function") {
            const cleanup = forwardedRef(node);
            if (cleanup) return () => { localRef.current = null; cleanup(); };
        } else if (forwardedRef) forwardedRef.current = node;
    }, [forwardedRef]);
    return [localRef, setRef] as const;
}

function Toast({
    open,
    onOpenChange,
    title,
    description,
    action,
    variant = "info",
    statusLabel,
    closeLabel = "Dismiss notification",
    duration = 7000,
    paused = false,
    onPointerEnter, onPointerLeave, onFocusCapture, onBlurCapture,
    ref: forwardedRef,
    className,
    ...props
}: ToastProps) {
    validateDuration(duration);
    const [hostRef, setHostRef] = useToastElementRef(forwardedRef);
    const returnFocus = useRef<HTMLElement | null>(null);
    const latestChange = useRef(onOpenChange);
    const clock = useRef({ duration, remaining: duration });
    const [hovered, setHovered] = useState(false);
    const [focused, setFocused] = useState(false);
    const [pageHidden, setPageHidden] = useState(false);
    useEffect(() => { latestChange.current = onOpenChange; }, [onOpenChange]);
    useEffect(() => {
        const update = () => setPageHidden(document.hidden);
        update();
        document.addEventListener("visibilitychange", update);
        return () => document.removeEventListener("visibilitychange", update);
    }, []);
    useEffect(() => {
        if (open && document.activeElement instanceof HTMLElement) {
            returnFocus.current = document.activeElement;
        }
        if (!open) { setHovered(false); setFocused(false); }
    }, [open]);
    const timerPaused = paused || hovered || focused || pageHidden;
    useEffect(() => {
        if (!open || clock.current.duration !== duration) {
            clock.current = { duration, remaining: duration };
        }
        if (!open || duration === 0 || timerPaused) return;
        const started = Date.now();
        const timer = setTimeout(() => latestChange.current(false), clock.current.remaining);
        return () => {
            clearTimeout(timer);
            clock.current.remaining = Math.max(0,
                clock.current.remaining - (Date.now() - started));
        };
    }, [open, duration, timerPaused]);

    if (!open) return null;

    return (
        <div
            ref={setHostRef}
            data-ui="toast"
            data-variant={variant}
            data-surface="status"
            className={cn(
                "pointer-events-auto min-w-0 rounded-sm border border-border " +
                "border-l-4 bg-surface p-[var(--space-4)] text-foreground " +
                "shadow-[var(--shadow-float)]",
                variant === "error" && "border-l-danger",
                variant === "success" && "border-l-success",
                variant === "warning" && "border-l-warning",
                variant === "info" && "border-l-accent",
                className,
            )}
            {...props}
            onPointerEnter={(event) => { setHovered(true); onPointerEnter?.(event); }}
            onPointerLeave={(event) => { setHovered(false); onPointerLeave?.(event); }}
            onFocusCapture={(event) => { setFocused(true); onFocusCapture?.(event); }}
            onBlurCapture={(event) => {
                if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false);
                onBlurCapture?.(event);
            }}
        >
            <div data-slot="surface-header"
                className="flex items-start gap-[var(--space-3)]">
                <div className="min-w-0 flex-1"
                    role={variant === "error" ? "alert" : "status"}
                    aria-atomic="true">
                    <span data-slot="surface-meta"
                        className="text-xs font-semibold uppercase text-muted">
                        {statusLabel ?? variantLabel[variant]}
                    </span>
                    <p data-slot="surface-title"
                        className="m-0 mt-1 text-sm font-semibold [overflow-wrap:anywhere]">{title}</p>
                    {description && (
                        <p className="mb-0 mt-1 text-sm text-muted [overflow-wrap:anywhere]">
                            {description}
                        </p>
                    )}
                </div>
                <button
                    type="button"
                    data-slot="surface-action"
                    aria-label={closeLabel}
                    className={
                        "-mr-1 -mt-1 shrink-0 rounded-sm p-1 text-muted " +
                        "hover:bg-surface-subtle hover:text-foreground " +
                        "focus-visible:outline-2 focus-visible:outline-focus"
                    }
                    onClick={() => {
                        const ownsFocus = hostRef.current?.contains(document.activeElement);
                        onOpenChange(false);
                        if (ownsFocus && returnFocus.current?.isConnected) {
                            returnFocus.current.focus();
                        }
                    }}
                >
                    <span aria-hidden="true">×</span>
                </button>
            </div>
            {action && <div className="mt-[var(--space-3)]">{action}</div>}
        </div>
    );
}

type ToastDraft = Pick<
    ToastProps,
    "title" | "description" | "action" | "variant" | "statusLabel" |
    "closeLabel" | "duration"
> & {
    dedupeKey?: string;
};

type ToastNotice = ToastDraft & { id: number };

function validateDuration(duration: number) {
    if (!Number.isFinite(duration) || duration < 0 || duration > 2147483647) {
        throw new RangeError("Toast duration must be between 0 and 2147483647 milliseconds.");
    }
}

function validateQueueOptions(maxVisible: number, duration: number) {
    if (!Number.isInteger(maxVisible) || maxVisible < 1) {
        throw new RangeError("Toast queue maxVisible must be a positive integer.");
    }
    validateDuration(duration);
}

type ToastQueueOptions = { maxVisible?: number; duration?: number };

function useToastQueue(options: number | ToastQueueOptions = {}) {
    const { maxVisible = 3, duration = 7000 } = typeof options === "number"
        ? { maxVisible: options } : options;
    validateQueueOptions(maxVisible, duration);

    const [notices, setNotices] = useState<ToastNotice[]>([]);
    const nextId = useRef(0);

    const enqueue = useCallback((draft: ToastDraft) => {
        if (draft.duration !== undefined) validateDuration(draft.duration);
        const id = ++nextId.current;
        setNotices((current) => {
            if (draft.dedupeKey !== undefined && current.some(
                (notice) => notice.dedupeKey === draft.dedupeKey,
            )) {
                return current;
            }
            return [{ ...draft, id }, ...current];
        });
    }, []);

    const dismiss = useCallback((id: number) => {
        setNotices((current) => current.filter((notice) => notice.id !== id));
    }, []);
    const dismissAll = useCallback(() => setNotices([]), []);

    return {
        notices, maxVisible, duration,
        visible: notices.slice(0, maxVisible),
        pendingCount: Math.max(0, notices.length - maxVisible),
        enqueue,
        dismiss,
        dismissAll,
    };
}

type ToastQueueProps = Omit<ToastRegionProps, "children"> & {
    notices: readonly ToastNotice[];
    onDismiss: (id: number) => void;
    onDismissAll?: () => void;
    maxVisible?: number;
    duration?: number;
    label?: string;
    closeAllLabel?: string;
};

function ToastQueue({
    notices,
    onDismiss,
    onDismissAll,
    maxVisible = 3,
    duration = 7000,
    label = "알림 목록",
    closeAllLabel = "전체 닫기",
    onPointerEnter, onPointerLeave, onFocusCapture, onBlurCapture,
    ref: forwardedRef,
    ...props
}: ToastQueueProps) {
    validateQueueOptions(maxVisible, duration);
    const listId = useId();
    const [regionRef, setRegionRef] = useToastElementRef(forwardedRef);
    const returnFocus = useRef<HTMLElement | null>(null);
    const previousCount = useRef(0);
    const [expanded, setExpanded] = useState(false);
    const [hovered, setHovered] = useState(false);
    const [focused, setFocused] = useState(false);
    useEffect(() => {
        if (previousCount.current === 0 && notices.length > 0 &&
            document.activeElement instanceof HTMLElement &&
            !regionRef.current?.contains(document.activeElement)) {
            returnFocus.current = document.activeElement;
        }
        previousCount.current = notices.length;
        if (notices.length === 0) {
            setExpanded(false); setHovered(false); setFocused(false);
        }
    }, [notices.length]);
    if (notices.length === 0) return null;
    const isExpanded = expanded && notices.length > 1;
    const layers = Math.min(notices.length, maxVisible) - 1;
    return (
        <ToastRegion {...props} ref={setRegionRef} role="region" aria-label={label}
            data-ui="toast-queue" data-expanded={isExpanded}
            onPointerEnter={(event) => { setHovered(true); onPointerEnter?.(event); }}
            onPointerLeave={(event) => { setHovered(false); onPointerLeave?.(event); }}
            onFocusCapture={(event) => { setFocused(true); onFocusCapture?.(event); }}
            onBlurCapture={(event) => {
                if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false);
                onBlurCapture?.(event);
            }}>
            <div className={
                "pointer-events-auto flex flex-wrap items-center justify-between " +
                "gap-2 rounded-sm border border-border bg-surface px-3 py-2 " +
                "text-xs text-foreground shadow-[var(--shadow-float)]"
            }>
                <span>{notices.length}개 알림</span>
                <div className="flex flex-wrap items-center gap-2">
                    {notices.length > 1 && <button type="button"
                        aria-expanded={isExpanded} aria-controls={listId}
                        onClick={() => setExpanded(!isExpanded)} className={
                            "rounded-sm px-2 py-1 text-accent " +
                            "focus-visible:outline-2 focus-visible:outline-focus"
                        }>{isExpanded ? "알림 접기" : "이전 알림 펼치기"}</button>}
                    <button type="button" onClick={() => {
                        const ownsFocus = regionRef.current?.contains(document.activeElement);
                        if (onDismissAll) onDismissAll();
                        else notices.forEach((notice) => onDismiss(notice.id));
                        if (ownsFocus && returnFocus.current?.isConnected) returnFocus.current.focus();
                    }} className={
                        "rounded-sm px-2 py-1 text-muted hover:text-foreground " +
                        "focus-visible:outline-2 focus-visible:outline-focus"
                    }>{closeAllLabel}</button>
                </div>
            </div>
            <div className="relative isolate" style={{ paddingBottom: isExpanded ? 0 : layers * 10 }}>
                {!isExpanded && Array.from({ length: layers }, (_, index) => (
                    <div key={index} aria-hidden="true" data-slot="toast-stack-layer"
                        data-surface="status" className={
                            "absolute inset-x-0 top-0 " +
                            "rounded-sm border border-border bg-surface shadow-[var(--shadow-float)]"
                        } style={{ height: `calc(100% - ${layers * 10}px)`,
                            transform: `translateY(${(layers - index) * 10}px) scaleX(${Math.max(0.25, 1 - (layers - index) * 0.035)})` }} />
                ))}
                <div id={listId} data-slot="toast-stack-list" className={cn(
                    "relative grid gap-2",
                    isExpanded && "pointer-events-auto overflow-y-auto overscroll-contain",
                )} style={isExpanded ? { maxHeight: `min(${maxVisible * 10}rem, calc(100dvh - 8rem))` } : undefined}>
                    {notices.map((notice, index) => (
                        <div key={notice.id} data-slot="toast-entry" hidden={!isExpanded && index > 0}>
                            <Toast
                                open
                                onOpenChange={(open) => {
                                    if (!open) onDismiss(notice.id);
                                }}
                                title={notice.title}
                                description={notice.description}
                                action={notice.action}
                                variant={notice.variant}
                                statusLabel={notice.statusLabel}
                                closeLabel={notice.closeLabel}
                                duration={notice.duration ?? duration}
                                paused={isExpanded || hovered || focused || index > 0}
                            />
                        </div>
                    ))}
                </div>
            </div>
        </ToastRegion>
    );
}

export { ToastRegion, Toast, ToastQueue, useToastQueue };
export type {
    ToastRegionProps, ToastProps, ToastDraft, ToastNotice,
    ToastQueueProps, ToastQueueOptions,
};
